import{_ as t}from"./chunks/BluKon_FW.DkVvdChq.js";import{_ as r,o as a,c as o,a3 as i}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Firmware del bridge","description":"","frontmatter":{"source_hash":"59d10a9889","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/bridgeFW.md","filePath":"it/troubleshoot/bridgeFW.md"}'),l={name:"it/troubleshoot/bridgeFW.md"};function n(s,e,d,p,c,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="blucon" tabindex="-1">Blucon <a class="header-anchor" href="#blucon" aria-label="Permalink to &quot;Blucon {#blucon}&quot;">​</a></h3><p>Non puoi aggiornare né riportare a una versione precedente il firmware di questi dispositivi.<br> Per conoscere la versione attuale del firmware devi installare l&#39;<a href="https://www.ambrosiasys.com/our-products/blucon/" target="_blank" rel="noreferrer">app del produttore</a>: la trovi nella sezione Informazioni...</p><img src="'+t+'" style="zoom:55%;"><p>Le versioni di firmware più vecchie supportano Libre 1.<br> Per Libre 14 giorni USA e Libre 2 ti serve un dispositivo recente con firmware almeno 4.2 e un algoritmo Out Of Process (OOP).</p><p><strong>I firmware più recenti, dalla 8.6 in su, non supportano xDrip.</strong></p><h3 id="miaomiao" tabindex="-1">MiaoMiao <a class="header-anchor" href="#miaomiao" aria-label="Permalink to &quot;MiaoMiao {#miaomiao}&quot;">​</a></h3><p>Il firmware consigliato è:</p><table tabindex="0"><thead><tr><th>Dispositivo</th><th>Firmware</th></tr></thead><tbody><tr><td>MiaoMiao</td><td>39</td></tr><tr><td>MiaoMiao 2</td><td>7</td></tr><tr><td>MiaoMiao 3</td><td>il più recente</td></tr></tbody></table><p>Per aggiornare il firmware devi prima usare <a href="./systemstatus.html#restart-collector-forget-device">Dimentica questo dispositivo</a> in Stato del sistema di xDrip.</p><p>Installa l&#39;<a href="http://tomato.cool/" target="_blank" rel="noreferrer">app del produttore</a>, che aggiornerà automaticamente il firmware del tuo miaomiao.</p><p>Una volta aggiornato, disinstalla l&#39;app, resetta il dispositivo e usa <a href="./../install/libreBT.html#connect-bluetooth-bridge">Scansione Bluetooth</a> in xDrip per ricollegarlo.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 22/11/2026</em></a></p>',13)])])}const f=r(l,[["render",n]]);export{b as __pageData,f as default};
